// What each recording tool declares for each capability, as the reference sees it. Generated by hand from docs/reference/daw/matrix.md
// (itself generated from the Go adapters' `Declares()`); capabilityMatrix.test.ts fails when the two disagree, so a change to an adapter
// shows up here as a red test, not as a stale table. The app never words a level as "Experimental" (#2251): Supported and Experimental are both `yes`.
// `no` covers Unsupported and, for Audacity 4, Not reachable (it has no scripting pipe).

import type { DawCapabilityKey } from '../api/contracts/daw';

export type MatrixCell = 'yes' | 'soon' | 'no';

/** The columns, in the order of each row's cells. */
export const MATRIX_TOOLS = ['REAPER', 'Audacity 3', 'Audacity 4', 'Built-in recorder'] as const;

